{
  "name": "opencode-supernudge",
  "private": true,
  "type": "module",
  "main": "index.ts",
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.5",
    "@opencode-ai/sdk": "^1.19.5",
    "@types/node": "^24.0.0"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugin": ["./index.ts"]
}

import type { Plugin, PluginInput } from "@opencode-ai/plugin"
import { parse as parseJsonc } from "jsonc-parser"
import type { ParseError } from "jsonc-parser"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { SubAgentMessageInjector } from "./injectors/sub-agent-message-injector.ts"
import { shouldSkipOnRegex } from "./injectors/regex-skip.ts"
import type { NormalMessageDelivery } from "./turn-bound-injector.ts"

type Position = "start" | "end"

type PromptConfig = {
  "injection.interval": number
  "injection.alwaysOnFirstMessage": boolean
  "injection.resetCounterOnCompaction": boolean
  "position.normalMessage": Position
  "position.subagent": Position
  "position.compaction": Position
  "enabled.normalMessage": boolean
  "enabled.subagentSystemPromptNudge": boolean
  "enabled.subagentAutonomousWorkNudge": boolean
  "enabled.compaction": boolean
  "wrapper.prefix": string
  "wrapper.suffix": string
  "nudge.separator": string
  "nudge.enableTitlePrefix": boolean
  "nudge.trim": boolean
  "nudge.visible": boolean
  "nudge.visibleMarker": boolean
  "injection.skipFirstMessageBelowChars": number
  "injection.subagentInterval": number
  "injection.subagentAlwaysOnFirst": boolean
  "injection.subagentResetOnCompaction": boolean
  "injection.skipOnRegexMatch": string[]
}

type PromptEntry = string | ({ path: string } & Partial<PromptConfig>)

type Config = PromptConfig & {
  "prompts": PromptEntry[],
  "currentWorkingDirectory.configFilePath": string,
  "currentWorkingDirectory.configEnabled": boolean
}

type ResolvedPrompt = PromptConfig & { content: string; title: string; explicitVisibleMarker: boolean }

export const DEFAULTS: Config = {
  "prompts": [],
  "injection.interval": 1,
  "injection.alwaysOnFirstMessage": true,
  "injection.resetCounterOnCompaction": true,
  "position.normalMessage": "start",
  "position.subagent": "start",
  "position.compaction": "start",
  "enabled.normalMessage": true,
  "enabled.subagentSystemPromptNudge": true,
  "enabled.compaction": true,
  "wrapper.prefix": "<opencode-supernudge>",
  "wrapper.suffix": "</opencode-supernudge>",
  "nudge.separator": "\n\n",
  "nudge.enableTitlePrefix": true,
  "nudge.trim": true,
  "nudge.visible": true,
  "nudge.visibleMarker": true,
  "injection.skipFirstMessageBelowChars": 3,
  "enabled.subagentAutonomousWorkNudge": true,
  "injection.subagentInterval": 1,
  "injection.subagentAlwaysOnFirst": true,
  "injection.subagentResetOnCompaction": true,
  "injection.skipOnRegexMatch": [],
  "currentWorkingDirectory.configFilePath": "./.opencode/com.kevincojean.opencode-supernudge/supernudge-configuration.jsonc",
  "currentWorkingDirectory.configEnabled": true,
}

function withTitle(prompt: ResolvedPrompt): string {
  if (!prompt["nudge.enableTitlePrefix"]) return prompt.content
  return `[${prompt.title}] ${prompt.content}`
}

function wrapString(content: string, prefix: string, suffix: string): string {
  const parts: string[] = []
  if (prefix) parts.push(prefix)
  parts.push(content)
  if (suffix) parts.push(suffix)
  return parts.join("\n")
}

function wrapArray(items: string[], prefix: string, suffix: string): string[] {
  const result: string[] = []
  if (prefix) result.push(prefix)
  result.push(...items)
  if (suffix) result.push(suffix)
  return result
}

function resolvePath(p: string, baseDir: string): string {
  if (p.startsWith("~")) {
    return path.join(os.homedir(), p.slice(1))
  }
  const home = process.env.HOME
  const withHome = home ? p.split("$HOME").join(home) : p
  if (!path.isAbsolute(withHome)) {
    return path.resolve(baseDir, withHome)
  }
  return withHome
}

function loadLocalConfig(configPath: string, client: PluginInput["client"]): Config | null {
  if (!fs.existsSync(configPath)) return null
  const text = fs.readFileSync(configPath, "utf-8")
  const errors: ParseError[] = []
  const parsed = parseJsonc(text, errors, { allowTrailingComma: true })
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    client.tui.showToast({
      body: {
        title: "SuperNudge",
        message: `Failed to parse local config at ${configPath}: ${errors.map(e => `ParseError at offset ${e.offset}`).join(", ")}`,
        variant: "error"
      }
    })
    return null
  }
  return { ...DEFAULTS, ...(parsed as Record<string, unknown>) } as Config
}

const LOCALLY_OVERRIDABLE_KEYS = new Set<keyof Config>(["prompts"])

function mergeConfigs(global: Config, local: Config): Config {
  const merged = { ...global }
  for (const key of Object.keys(local) as (keyof Config)[]) {
    if (LOCALLY_OVERRIDABLE_KEYS.has(key)) {
      if (key === "prompts") {
        merged[key] = [...global[key], ...local[key]] as Config["prompts"]
      }
    }
  }
  return merged
}

function loadConfig(configPath: string): Config {
  if (!fs.existsSync(configPath)) return DEFAULTS
  const text = fs.readFileSync(configPath, "utf-8")
  const errors: ParseError[] = []
  const parsed = parseJsonc(text, errors, { allowTrailingComma: true })
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return DEFAULTS
  }
  return { ...DEFAULTS, ...(parsed as Record<string, unknown>) } as Config
}

function resolvePrompts(
  prompts: readonly PromptEntry[],
  defaults: PromptConfig,
  baseDir: string,
): ResolvedPrompt[] {
  const result: ResolvedPrompt[] = []
  for (const entry of prompts) {
    const obj = typeof entry === "string" ? { path: entry } : entry
    const resolved: PromptConfig = { ...defaults, ...obj } as PromptConfig
    const filePath = resolvePath(obj.path, baseDir)
    if (!fs.existsSync(filePath)) continue
    const rawContent = fs.readFileSync(filePath, "utf-8")
    const content = resolved["nudge.trim"] ? rawContent.trim() : rawContent
    if (content) {
      const title = path.basename(filePath, path.extname(filePath)).toLowerCase()
      const explicitVisibleMarker = "nudge.visibleMarker" in obj && obj["nudge.visibleMarker"] === true
      result.push({ ...resolved, content, title, explicitVisibleMarker })
    }
  }
  return result
}

function getMergedNudge(globalConfigPath: string, baseDir: string, client: PluginInput["client"]): { prompts: ResolvedPrompt[]; prefix: string; suffix: string; separator: string } {
  const globalConfig = loadConfig(globalConfigPath)
  let mergedConfig = globalConfig

  if (globalConfig["currentWorkingDirectory.configEnabled"]) {
    const localPath = resolvePath(globalConfig["currentWorkingDirectory.configFilePath"], baseDir)
    const localConfig = loadLocalConfig(localPath, client)
    if (localConfig) {
      mergedConfig = mergeConfigs(globalConfig, localConfig)
    }
  }

  const { prompts, ...defaults } = mergedConfig
  return {
    prompts: resolvePrompts(prompts, defaults, baseDir),
    prefix: defaults["wrapper.prefix"],
    suffix: defaults["wrapper.suffix"],
    separator: defaults["nudge.separator"],
  }
}

const DEFAULT_CONFIG_PATH = path.join(
  os.homedir(),
  ".config/opencode/opencode-supernudge/supernudge-configuration.jsonc",
)

function computeDeliveries(
  prompts: ResolvedPrompt[],
  counts: number[],
  messageText: string,
  client: PluginInput["client"],
  visible: boolean,
  prefix: string,
  suffix: string,
  separator: string,
): NormalMessageDelivery[] {
  const startTexts: string[] = []
  const endTexts: string[] = []
  let startMarker = false
  let endMarker = false

  for (let i = 0; i < prompts.length; i++) {
    const prompt = prompts[i]
    if (!prompt["enabled.normalMessage"]) continue
    const count = counts[i] ?? 0
    const interval = prompt["injection.interval"]
    const shouldInject =
      interval <= 1 ||
      (count === 1
        ? prompt["injection.alwaysOnFirstMessage"]
        : (count - 1) % interval === 0)
    if (!shouldInject) continue
    if (messageText.length <= prompt["injection.skipFirstMessageBelowChars"]) continue
    if (shouldSkipOnRegex(messageText, prompt["injection.skipOnRegexMatch"], client)) continue
    if (prompt["nudge.visible"] !== visible) continue

    const block = withTitle(prompt)
    if (prompt["position.normalMessage"] === "end") {
      endTexts.push(block)
      endMarker = endMarker || prompt["nudge.visibleMarker"]
    } else {
      startTexts.push(block)
      startMarker = startMarker || prompt["nudge.visibleMarker"]
    }
  }

  const deliveries: NormalMessageDelivery[] = []
  if (startTexts.length > 0) {
    let block = startTexts.join(separator)
    if (startMarker) block = wrapString(block, prefix, suffix)
    deliveries.push({ position: "start", text: block })
  }
  if (endTexts.length > 0) {
    let block = endTexts.join(separator)
    if (endMarker) block = wrapString(block, prefix, suffix)
    deliveries.push({ position: "end", text: block })
  }
  return deliveries
}

const plugin: Plugin = async (input, options) => {
  const baseDir = input.directory
  const client = input.client
  const optConfigPath = options?.configPath
  const configPath = typeof optConfigPath === "string"
    ? optConfigPath
    : DEFAULT_CONFIG_PATH

  const counters = new Map<string, number[]>()

  const subAgentInjector = new SubAgentMessageInjector(() => getMergedNudge(configPath, baseDir, client).prompts, client)

  subAgentInjector.setPrimaryInvisibleProvider((sessionID, messageText) => {
    const { prompts: resolvedPrompts, prefix, suffix, separator } = getMergedNudge(configPath, baseDir, client)
    if (resolvedPrompts.length === 0) return []

    const promptCounts = counters.get(sessionID)
    if (!promptCounts) return []

    return computeDeliveries(resolvedPrompts, promptCounts, messageText, client, false, prefix, suffix, separator)
  })

  return {
    ...subAgentInjector.hooks(),
    "chat.message": async (input, output) => {
      const { prompts: resolvedPrompts, prefix, suffix, separator } = getMergedNudge(configPath, baseDir, client)
      if (resolvedPrompts.length === 0) return

      let promptCounts = counters.get(input.sessionID)
      if (!promptCounts || promptCounts.length !== resolvedPrompts.length) {
        promptCounts = new Array(resolvedPrompts.length).fill(0)
      }
      for (let i = 0; i < promptCounts.length; i++) {
        promptCounts[i]++
      }

      const messageTextPart = output.parts.find(p => p.type === "text" && "text" in p) as { text: string } | undefined
      const deliveries = computeDeliveries(
        resolvedPrompts,
        promptCounts,
        messageTextPart?.text ?? "",
        client,
        true,
        prefix,
        suffix,
        separator,
      )
      counters.set(input.sessionID, promptCounts)

      const target = output.parts.find(p => p.type === "text" && "text" in p) as { text: string } | undefined
      if (!target) return

      for (const delivery of deliveries) {
        target.text = delivery.position === "start"
          ? delivery.text + "\n\n" + target.text
          : target.text + "\n\n" + delivery.text
      }
    },
    "experimental.chat.system.transform": async (input, output) => {
      if (input.sessionID) return
      const { prompts: resolvedPrompts, prefix, suffix } = getMergedNudge(configPath, baseDir, client)
      if (resolvedPrompts.length === 0) return

      const startPrompts: string[] = []
      const endPrompts: string[] = []
      const systemText = output.system.join("\n")

      for (const prompt of resolvedPrompts) {
        if (!prompt["enabled.subagentSystemPromptNudge"]) continue

        if (shouldSkipOnRegex(systemText, prompt["injection.skipOnRegexMatch"], client)) continue

        if (prompt["position.subagent"] === "end") {
          endPrompts.push(withTitle(prompt))
        } else {
          startPrompts.push(withTitle(prompt))
        }
      }

      if (startPrompts.length > 0) {
        const block = wrapArray(startPrompts, prefix, suffix)
        output.system.unshift(...block)
      }
      if (endPrompts.length > 0) {
        const block = wrapArray(endPrompts, prefix, suffix)
        output.system.push(...block)
      }
    },
    "experimental.session.compacting": async (input, output) => {
      const { prompts: resolvedPrompts, prefix, suffix } = getMergedNudge(configPath, baseDir, client)

      subAgentInjector.resetOnCompaction(input.sessionID, resolvedPrompts)

      const promptCounts = counters.get(input.sessionID)
      if (promptCounts) {
        for (let i = 0; i < resolvedPrompts.length && i < promptCounts.length; i++) {
          if (resolvedPrompts[i]["injection.resetCounterOnCompaction"]) {
            promptCounts[i] = 0
          }
        }
      }

      const startPrompts: string[] = []
      const endPrompts: string[] = []
      const contextText = output.context.join("\n")

      for (const prompt of resolvedPrompts) {
        if (!prompt["enabled.compaction"]) continue

        if (shouldSkipOnRegex(contextText, prompt["injection.skipOnRegexMatch"], client)) continue

        if (prompt["position.compaction"] === "end") {
          endPrompts.push(withTitle(prompt))
        } else {
          startPrompts.push(withTitle(prompt))
        }
      }

      if (startPrompts.length > 0) {
        const block = wrapArray(startPrompts, prefix, suffix)
        output.context.unshift(...block)
      }
      if (endPrompts.length > 0) {
        const block = wrapArray(endPrompts, prefix, suffix)
        output.context.push(...block)
      }
    },
    ...subAgentInjector.hooks(),
  }
}

export default plugin

